const DEFAULT_MAX_QUEUED_DURATION: Duration = Duration::from_secs(60);
const HEADER_SORA_PROOF: &str = "sora-proof";
const HEADER_SORA_NAME: &str = "sora-name";
const HEADER_SORA_PROOF_STATUS: &str = "sora-proof-status";

/// `Result` with [`QueryError`] as an error
pub type QueryResult<T> = core::result::Result<T, QueryError>;

fn parse_canonical_i105_account_id(value: &str, field: &str) -> Result<AccountId> {
    let trimmed = value.trim();
    if trimmed != value {
        return Err(eyre!("{field} must not contain surrounding whitespace"));
    }
    let parsed = AccountId::parse_encoded(trimmed)
        .map_err(|err| eyre!("{field} must be a canonical I105 account id: {err}"))?;
    if parsed.canonical() != value {
        return Err(eyre!(
            "{field} must use the canonical domainless I105 representation"
        ));
    }
    Ok(parsed.into_account_id())
}

fn ensure_canonical_i105_account_id(value: &str, field: &str) -> Result<()> {
    parse_canonical_i105_account_id(value, field).map(drop)
}

fn parse_canonical_account_alias(value: &str, field: &str) -> Result<AccountAliasName> {
    let alias = value
        .parse::<AccountAliasName>()
        .map_err(|error| eyre!("invalid {field}: {error}"))?;
    if alias.to_string() != value {
        return Err(eyre!(
            "{field} must use its canonical textual representation"
        ));
    }
    Ok(alias)
}

fn ensure_typed_account_alias_is_canonical(alias: &AccountAliasName, field: &str) -> Result<()> {
    if !alias.is_canonical() {
        return Err(eyre!("{field} must be a canonical account alias"));
    }
    let canonical = alias.to_string();
    let reparsed = parse_canonical_account_alias(&canonical, field)?;
    if reparsed != *alias {
        return Err(eyre!("{field} must be a canonical account alias"));
    }
    Ok(())
}

fn canonical_alias_read_source(source: Option<String>, field: &str) -> Result<Option<String>> {
    let Some(source) = source else {
        return Ok(None);
    };
    let bytes = source.as_bytes();
    if bytes.is_empty()
        || bytes.len() > 64
        || !bytes[0].is_ascii_lowercase()
        || !bytes
            .iter()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || *byte == b'_')
    {
        return Err(eyre!(
            "{field} must be a canonical lowercase ASCII identifier"
        ));
    }
    Ok(Some(source))
}

fn alias_text_cmp(left: &AccountAliasName, right: &AccountAliasName) -> std::cmp::Ordering {
    left.to_string().cmp(&right.to_string())
}

fn decode_account_alias_resolution(
    response: &Response<Vec<u8>>,
    expected_alias: &AccountAliasName,
) -> Result<Option<AccountAliasResolutionV1>> {
    match response.status() {
        StatusCode::NOT_FOUND => Ok(None),
        StatusCode::OK => {
            let wire: AccountAliasResolutionWireV1 = norito::json::from_slice(response.body())
                .wrap_err("decode account-alias resolution response")?;
            let alias = parse_canonical_account_alias(&wire.alias, "response.alias")?;
            if &alias != expected_alias {
                return Err(eyre!(
                    "account-alias response selector differs from the requested alias"
                ));
            }
            let account_id =
                parse_canonical_i105_account_id(&wire.account_id, "response.account_id")?;
            AccountAliasResolutionV1::try_new(
                alias,
                account_id,
                wire.index.map(AliasIndex),
                wire.source,
            )
            .map(Some)
        }
        status => Err(eyre!(
            "account-alias resolution failed with HTTP status {status}"
        )),
    }
}

fn decode_account_alias_index_resolution(
    response: &Response<Vec<u8>>,
    expected_index: AliasIndex,
) -> Result<Option<AccountAliasIndexResolutionV1>> {
    match response.status() {
        StatusCode::NOT_FOUND => Ok(None),
        StatusCode::OK => {
            let wire: AccountAliasIndexResolutionWireV1 = norito::json::from_slice(response.body())
                .wrap_err("decode account-alias index resolution response")?;
            if wire.index != expected_index.0 {
                return Err(eyre!(
                    "account-alias index response selector differs from the requested index"
                ));
            }
            let alias = parse_canonical_account_alias(&wire.alias, "response.alias")?;
            let account_id =
                parse_canonical_i105_account_id(&wire.account_id, "response.account_id")?;
            AccountAliasIndexResolutionV1::try_new(
                AliasIndex(wire.index),
                alias,
                account_id,
                wire.source,
            )
            .map(Some)
        }
        status => Err(eyre!(
            "account-alias index resolution failed with HTTP status {status}"
        )),
    }
}

fn decode_account_aliases_by_account(
    response: &Response<Vec<u8>>,
    request: &AccountAliasesByAccountRequestV1,
) -> Result<Option<AccountAliasesByAccountV1>> {
    match response.status() {
        StatusCode::NOT_FOUND => Ok(None),
        StatusCode::OK => {
            let wire: AccountAliasesByAccountWireV1 = norito::json::from_slice(response.body())
                .wrap_err("decode account aliases-by-account response")?;
            if wire.account_id != request.account_id().to_string() {
                return Err(eyre!(
                    "account aliases-by-account response selector differs from the requested account"
                ));
            }
            let account_id =
                parse_canonical_i105_account_id(&wire.account_id, "response.account_id")?;
            if &account_id != request.account_id() {
                return Err(eyre!(
                    "account aliases-by-account response selector differs from the requested account"
                ));
            }
            if wire.total != u64::try_from(wire.items.len()).unwrap_or(u64::MAX) {
                return Err(eyre!(
                    "account aliases-by-account response total differs from its item count"
                ));
            }

            let mut previous_alias: Option<String> = None;
            let mut items = Vec::with_capacity(wire.items.len());
            for (index, item) in wire.items.into_iter().enumerate() {
                if previous_alias
                    .as_ref()
                    .is_some_and(|previous| previous >= &item.alias)
                {
                    return Err(eyre!(
                        "account aliases-by-account response items are not in strict canonical alias order at index {index}"
                    ));
                }
                previous_alias = Some(item.alias.clone());
                let alias = parse_canonical_account_alias(
                    &item.alias,
                    &format!("response.items[{index}].alias"),
                )?;
                if item.dataspace != alias.dataspace.as_ref()
                    || item.domain.as_deref() != alias.domain.as_ref().map(AsRef::as_ref)
                {
                    return Err(eyre!(
                        "account aliases-by-account response item {index} has scope fields that differ from its alias"
                    ));
                }
                if request
                    .dataspace()
                    .is_some_and(|expected| expected != &alias.dataspace)
                    || request
                        .domain()
                        .is_some_and(|expected| alias.domain.as_ref() != Some(expected))
                {
                    return Err(eyre!(
                        "account aliases-by-account response item {index} falls outside the requested scope"
                    ));
                }
                items.push(AccountAliasListItemV1::try_new(alias, item.is_primary)?);
            }
            let source = canonical_alias_read_source(wire.source, "response.source")?;
            Ok(Some(AccountAliasesByAccountV1 {
                account_id,
                items,
                source,
            }))
        }
        status => Err(eyre!(
            "account aliases-by-account lookup failed with HTTP status {status}"
        )),
    }
}

fn onboarding_disposition_transition_allowed(
    planned: AliasPlanDispositionV1,
    live: AliasPlanDispositionV1,
) -> bool {
    use AliasPlanDispositionV1::{Create, NoOp, Repair};

    matches!(
        (planned, live),
        (Create, Create | Repair | NoOp) | (Repair, Repair | NoOp) | (NoOp, NoOp)
    )
}

fn validate_account_onboarding_token(token: &str) -> Result<&str> {
    let bytes = token.as_bytes();
    if !(32..=256).contains(&bytes.len()) || !bytes.iter().all(|byte| (0x21..=0x7e).contains(byte))
    {
        return Err(eyre!(
            "account onboarding token must contain 32 through 256 printable ASCII bytes without spaces"
        ));
    }
    Ok(token)
}

/// Filters for `/v1/zk/prover/reports` listing/counting/deletion endpoints.
#[derive(Debug, Default, Clone)]
pub struct ZkProverReportsFilter<'a> {
    /// Only successful reports
    pub ok_only: Option<bool>,
    /// Only failed reports
    pub failed_only: Option<bool>,
    /// Only error messages (alias for failed-only in some endpoints)
    pub errors_only: Option<bool>,
    /// Exact id filter
    pub id: Option<&'a str>,
    /// Content-type substring filter
    pub content_type: Option<&'a str>,
    /// Require a particular ZK1 tag (e.g., PROF, IPAK)
    pub has_tag: Option<&'a str>,
    /// Limit number of results
    pub limit: Option<u32>,
    /// Lower bound for `processed_ms`
    pub since_ms: Option<u64>,
    /// Upper bound for `processed_ms`
    pub before_ms: Option<u64>,
    /// Return only ids
    pub ids_only: Option<bool>,
    /// Sort order (`asc`/`desc`)
    pub order: Option<&'a str>,
    /// Offset for pagination
    pub offset: Option<u32>,
    /// Return only the latest matching report
    pub latest: Option<bool>,
    /// Return only messages payloads
    pub messages_only: Option<bool>,
}

/// Unsigned verifying-key registry transaction returned for local signing.
#[derive(Clone, Debug, PartialEq, Eq, JsonSerialize, JsonDeserialize)]
#[norito(deny_unknown_fields)]
pub struct ZkVkTransactionDraft {
    /// Always `false`; Torii has not submitted this transaction.
    pub submitted: bool,
    /// Canonical Norito `TransactionPayload` bytes encoded as padded base64.
    pub transaction_payload_b64: String,
    /// Exact transaction-payload prehash encoded as padded base64.
    pub signing_message_b64: String,
}

impl ZkProverReportsFilter<'_> {
    fn apply(&self, mut req: DefaultRequestBuilder) -> DefaultRequestBuilder {
        if let Some(true) = self.ok_only {
            req = req.param("ok_only", &"true");
        }
        if let Some(true) = self.failed_only {
            req = req.param("failed_only", &"true");
        }
        if let Some(true) = self.errors_only {
            req = req.param("errors_only", &"true");
        }
        if let Some(v) = self.id {
            req = req.param("id", &v);
        }
        if let Some(v) = self.content_type {
            req = req.param("content_type", &v);
        }
        if let Some(v) = self.has_tag {
            req = req.param("has_tag", &v);
        }
        if let Some(v) = self.limit {
            req = req.param("limit", &v);
        }
        if let Some(v) = self.since_ms {
            req = req.param("since_ms", &v);
        }
        if let Some(v) = self.before_ms {
            req = req.param("before_ms", &v);
        }
        if let Some(true) = self.ids_only {
            req = req.param("ids_only", &"true");
        }
        if let Some(v) = self.order {
            req = req.param("order", &v);
        }
        if let Some(v) = self.offset {
            req = req.param("offset", &v);
        }
        if let Some(true) = self.latest {
            req = req.param("latest", &"true");
        }
        if let Some(true) = self.messages_only {
            req = req.param("messages_only", &"true");
        }
        req
    }
}

/// Filters for `/v1/zk/proofs` list/count endpoints.
#[derive(Debug, Default, Clone)]
pub struct ZkProofsFilter<'a> {
    /// Exact backend (e.g., `halo2/ipa`).
    pub backend: Option<&'a str>,
    /// Status filter (`Submitted`, `Verified`, `Rejected`).
    pub status: Option<&'a str>,
    /// Require a specific ZK1 TLV tag (4 ASCII characters).
    pub has_tag: Option<&'a str>,
    /// Minimum `verified_at_height` (inclusive).
    pub verified_from_height: Option<u64>,
    /// Maximum `verified_at_height` (inclusive).
    pub verified_until_height: Option<u64>,
    /// Maximum number of results (server caps at 1000).
    pub limit: Option<u32>,
    /// Offset for server-side pagination.
    pub offset: Option<u32>,
    /// Sort order (`asc` or `desc`).
    pub order: Option<&'a str>,
    /// Return only `{ backend, hash }` objects when true.
    pub ids_only: Option<bool>,
}

impl ZkProofsFilter<'_> {
    fn apply(&self, mut req: DefaultRequestBuilder) -> DefaultRequestBuilder {
        if let Some(v) = self.backend {
            req = req.param("backend", &v);
        }
        if let Some(v) = self.status {
            req = req.param("status", &v);
        }
        if let Some(v) = self.has_tag {
            req = req.param("has_tag", &v);
        }
        if let Some(v) = self.verified_from_height {
            req = req.param("verified_from_height", &v);
        }
        if let Some(v) = self.verified_until_height {
            req = req.param("verified_until_height", &v);
        }
        if let Some(v) = self.limit {
            req = req.param("limit", &v);
        }
        if let Some(v) = self.offset {
            req = req.param("offset", &v);
        }
        if let Some(v) = self.order {
            req = req.param("order", &v);
        }
        if let Some(true) = self.ids_only {
            req = req.param("ids_only", &"true");
        }
        req
    }
}

fn validate_zk_proofs_filter(filter: &ZkProofsFilter<'_>) -> Result<()> {
    if let Some(backend) = filter.backend {
        require_verifier_backend_registry_label_v1(backend, "zk proofs filter backend")?;
    }
    Ok(())
}

fn validate_zk_ivm_json(value: &norito::json::Value, context: &str) -> Result<()> {
    let object = require_json_object(value, context)?;
    require_json_vk_ref(object, context, None)?;
    Ok(())
}

fn validate_zk_vk_submission_json(
    value: &norito::json::Value,
    context: &str,
    require_gas_schedule_id: bool,
) -> Result<()> {
    const FIELDS: [&str; 17] = [
        "authority",
        "backend",
        "name",
        "version",
        "circuit_id",
        "public_inputs_schema_hash_hex",
        "curve",
        "gas_schedule_id",
        "vk_len",
        "max_proof_bytes",
        "metadata_uri_cid",
        "vk_bytes_cid",
        "activation_height",
        "withdraw_height",
        "commitment_hex",
        "vk_bytes",
        "status",
    ];

    let object = require_json_object(value, context)?;
    if let Some(field) = object
        .keys()
        .find(|field| !FIELDS.contains(&field.as_str()))
    {
        return Err(eyre!("{context} contains unknown field {field}"));
    }
    let backend = require_json_backend_field(object, "backend", &format!("{context}.backend"))?;
    require_json_vk_name_field(object, "name", &format!("{context}.name"))?;
    let authority =
        require_json_non_empty_string_field(object, "authority", &format!("{context}.authority"))?;
    ensure_canonical_i105_account_id(authority, &format!("{context}.authority"))?;
    require_json_positive_u32_field(object, "version", &format!("{context}.version"))?;
    require_json_non_empty_string_field(object, "circuit_id", &format!("{context}.circuit_id"))?;
    require_json_hex32_field(
        object,
        "public_inputs_schema_hash_hex",
        &format!("{context}.public_inputs_schema_hash_hex"),
    )?;
    if require_gas_schedule_id {
        require_json_non_empty_string_field(
            object,
            "gas_schedule_id",
            &format!("{context}.gas_schedule_id"),
        )?;
    } else {
        validate_optional_json_non_empty_string_field(
            object,
            "gas_schedule_id",
            &format!("{context}.gas_schedule_id"),
        )?;
    }
    validate_optional_json_non_empty_string_field(object, "curve", &format!("{context}.curve"))?;
    validate_optional_json_non_empty_string_field(
        object,
        "metadata_uri_cid",
        &format!("{context}.metadata_uri_cid"),
    )?;
    validate_optional_json_non_empty_string_field(
        object,
        "vk_bytes_cid",
        &format!("{context}.vk_bytes_cid"),
    )?;
    validate_optional_json_u32_field(
        object,
        "max_proof_bytes",
        &format!("{context}.max_proof_bytes"),
    )?;
    validate_optional_json_status_field(object, "status", &format!("{context}.status"))?;
    validate_optional_json_height_range(object, context)?;
    validate_optional_json_vk_submission_bytes(object, backend, context)?;
    Ok(())
}

#[derive(Clone, Copy)]
enum ZkVkDraftOperation {
    Register,
    Update,
}

fn decode_canonical_zk_vk_base64(
    value: &str,
    max_decoded_bytes: usize,
    context: &str,
) -> Result<Vec<u8>> {
    let max_encoded_bytes = max_decoded_bytes.div_ceil(3).saturating_mul(4);
    if value.len() > max_encoded_bytes {
        return Err(eyre!("{context} exceeds its decoded byte limit"));
    }
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(value)
        .wrap_err_with(|| format!("{context} must be canonical padded base64"))?;
    if bytes.is_empty()
        || bytes.len() > max_decoded_bytes
        || base64::engine::general_purpose::STANDARD.encode(&bytes) != value
    {
        return Err(eyre!("{context} must be non-empty canonical padded base64"));
    }
    Ok(bytes)
}

fn decode_zk_vk_hex32(value: &str, context: &str) -> Result<[u8; 32]> {
    let normalized = normalize_hex32_lower(value, context)?;
    let bytes = hex::decode(normalized).wrap_err_with(|| format!("decode {context}"))?;
    let mut output = [0_u8; 32];
    output.copy_from_slice(&bytes);
    Ok(output)
}

fn expected_zk_vk_record_from_request(
    request: &norito::json::Value,
) -> Result<iroha_data_model::proof::VerifyingKeyRecord> {
    use iroha_data_model::{
        confidential::ConfidentialStatus,
        proof::{VerifyingKeyBox, VerifyingKeyRecord},
    };

    let object = require_json_object(request, "verifying-key draft request")?;
    let backend =
        require_json_backend_field(object, "backend", "verifying-key draft request.backend")?;
    let version =
        require_json_positive_u32_field(object, "version", "verifying-key draft request.version")?;
    let circuit_id = require_json_non_empty_string_field(
        object,
        "circuit_id",
        "verifying-key draft request.circuit_id",
    )?;
    let schema_hash = decode_zk_vk_hex32(
        require_json_non_empty_string_field(
            object,
            "public_inputs_schema_hash_hex",
            "verifying-key draft request.public_inputs_schema_hash_hex",
        )?,
        "verifying-key draft request.public_inputs_schema_hash_hex",
    )?;
    let backend_tag = iroha_data_model::zk::verifier_backend_registry_tag_v1(backend)
        .ok_or_else(|| eyre!("verifying-key draft request uses an unsupported backend"))?;
    let vk_bytes = validate_optional_json_base64_bytes_field(
        object,
        "vk_bytes",
        "verifying-key draft request.vk_bytes",
    )?;
    let commitment = match (
        vk_bytes.as_ref(),
        object
            .get("commitment_hex")
            .and_then(norito::json::Value::as_str),
    ) {
        (Some(bytes), _) => decode_zk_vk_hex32(
            &zk_vk_commitment_hex(backend, bytes)?,
            "verifying-key draft computed commitment",
        )?,
        (None, Some(commitment)) => {
            decode_zk_vk_hex32(commitment, "verifying-key draft request.commitment_hex")?
        }
        (None, None) => {
            return Err(eyre!(
                "verifying-key draft request must provide commitment material"
            ));
        }
    };
    let vk_len = if let Some(bytes) = vk_bytes.as_ref() {
        u32::try_from(bytes.len()).wrap_err("verifying-key draft key length exceeds u32")?
    } else {
        validate_optional_json_positive_u32_field(
            object,
            "vk_len",
            "verifying-key draft request.vk_len",
        )?
        .ok_or_else(|| eyre!("verifying-key draft request.vk_len is required"))?
    };
    let mut record = VerifyingKeyRecord::new_with_owner(
        version,
        circuit_id,
        None,
        "core",
        backend_tag,
        object
            .get("curve")
            .and_then(norito::json::Value::as_str)
            .unwrap_or("unknown"),
        schema_hash,
        commitment,
    );
    record.vk_len = vk_len;
    record.max_proof_bytes = validate_optional_json_u32_field(
        object,
        "max_proof_bytes",
        "verifying-key draft request.max_proof_bytes",
    )?
    .unwrap_or(0);
    record.gas_schedule_id = object
        .get("gas_schedule_id")
        .and_then(norito::json::Value::as_str)
        .map(str::to_owned);
    record.metadata_uri_cid = object
        .get("metadata_uri_cid")
        .and_then(norito::json::Value::as_str)
        .map(str::to_owned);
    record.vk_bytes_cid = object
        .get("vk_bytes_cid")
        .and_then(norito::json::Value::as_str)
        .map(str::to_owned);
    record.activation_height = object
        .get("activation_height")
        .and_then(norito::json::Value::as_u64);
    record.withdraw_height = object
        .get("withdraw_height")
        .and_then(norito::json::Value::as_u64);
    record.key = vk_bytes.map(|bytes| VerifyingKeyBox::new(backend.into(), bytes));
    record.status = match object.get("status").and_then(norito::json::Value::as_str) {
        None | Some("Active") => ConfidentialStatus::Active,
        Some("Proposed") => ConfidentialStatus::Proposed,
        Some("Withdrawn") => ConfidentialStatus::Withdrawn,
        Some(status) => {
            return Err(eyre!(
                "verifying-key draft request uses invalid status {status}"
            ));
        }
    };
    Ok(record)
}

fn decode_zk_vk_transaction_draft(
    body: &[u8],
    request: &norito::json::Value,
    expected_chain: &ChainId,
    operation: ZkVkDraftOperation,
) -> Result<ZkVkTransactionDraft> {
    let draft: ZkVkTransactionDraft = norito::json::from_slice(body)
        .wrap_err("decode verifying-key transaction draft response")?;
    if draft.submitted {
        return Err(eyre!(
            "verifying-key transaction draft must not claim server submission"
        ));
    }

    let payload_bytes = decode_canonical_zk_vk_base64(
        &draft.transaction_payload_b64,
        ZK_VK_DRAFT_MAX_TRANSACTION_PAYLOAD_BYTES,
        "verifying-key draft transaction_payload_b64",
    )?;
    let builder = TransactionBuilder::decode_payload(&payload_bytes)
        .wrap_err("decode canonical verifying-key transaction payload")?;
    let signing_message = decode_canonical_zk_vk_base64(
        &draft.signing_message_b64,
        Hash::LENGTH,
        "verifying-key draft signing_message_b64",
    )?;
    if signing_message.as_slice() != HashOf::new(builder.payload()).as_ref() {
        return Err(eyre!(
            "verifying-key draft signing_message_b64 does not match the transaction payload"
        ));
    }

    let object = require_json_object(request, "verifying-key draft request")?;
    let authority = parse_canonical_i105_account_id(
        require_json_non_empty_string_field(
            object,
            "authority",
            "verifying-key draft request.authority",
        )?,
        "verifying-key draft request.authority",
    )?;
    if builder.payload().chain != *expected_chain || builder.payload().authority != authority {
        return Err(eyre!(
            "verifying-key draft transaction payload changed the requested chain or authority"
        ));
    }

    let backend =
        require_json_backend_field(object, "backend", "verifying-key draft request.backend")?;
    let name = require_json_vk_name_field(object, "name", "verifying-key draft request.name")?;
    let expected_record = expected_zk_vk_record_from_request(request)?;
    let iroha_data_model::transaction::Executable::Instructions(instructions) =
        &builder.payload().instructions
    else {
        return Err(eyre!(
            "verifying-key draft transaction payload must contain native instructions"
        ));
    };
    if instructions.len() != 1 {
        return Err(eyre!(
            "verifying-key draft transaction payload must contain exactly one instruction"
        ));
    }
    let id_matches = match operation {
        ZkVkDraftOperation::Register => instructions[0]
            .as_any()
            .downcast_ref::<iroha_data_model::isi::verifying_keys::RegisterVerifyingKey>()
            .is_some_and(|instruction| {
                instruction.id.backend.as_str() == backend
                    && instruction.id.name == name
                    && instruction.record == expected_record
            }),
        ZkVkDraftOperation::Update => instructions[0]
            .as_any()
            .downcast_ref::<iroha_data_model::isi::verifying_keys::UpdateVerifyingKey>()
            .is_some_and(|instruction| {
                instruction.id.backend.as_str() == backend
                    && instruction.id.name == name
                    && instruction.record == expected_record
            }),
    };
    if !id_matches {
        return Err(eyre!(
            "verifying-key draft transaction payload does not contain the requested registry operation"
        ));
    }
    Ok(draft)
}

fn require_json_object<'a>(
    value: &'a norito::json::Value,
    context: &str,
) -> Result<&'a norito::json::Map> {
    value
        .as_object()
        .ok_or_else(|| eyre!("{context} must be a JSON object"))
}

fn require_json_backend_field<'a>(
    object: &'a norito::json::Map,
    field: &str,
    context: &str,
) -> Result<&'a str> {
    let backend = object
        .get(field)
        .and_then(norito::json::Value::as_str)
        .ok_or_else(|| eyre!("{context} must be a string"))?;
    require_verifier_backend_registry_label_v1(backend, context)
}

fn require_json_non_empty_string_field<'a>(
    object: &'a norito::json::Map,
    field: &str,
    context: &str,
) -> Result<&'a str> {
    let value = object
        .get(field)
        .and_then(norito::json::Value::as_str)
        .ok_or_else(|| eyre!("{context} must be a string"))?;
    if value.trim().is_empty() {
        return Err(eyre!("{context} must be non-empty"));
    }
    Ok(value)
}

fn require_json_vk_name_field<'a>(
    object: &'a norito::json::Map,
    field: &str,
    context: &str,
) -> Result<&'a str> {
    let value = require_json_non_empty_string_field(object, field, context)?;
    if value.contains(':') {
        return Err(eyre!("{context} must not contain ':'"));
    }
    Ok(value)
}

fn validate_optional_json_non_empty_string_field(
    object: &norito::json::Map,
    field: &str,
    context: &str,
) -> Result<()> {
    match object.get(field) {
        None => Ok(()),
        Some(value) if value.is_null() => Ok(()),
        Some(_) => {
            require_json_non_empty_string_field(object, field, context)?;
            Ok(())
        }
    }
}

fn require_json_positive_u32_field(
    object: &norito::json::Map,
    field: &str,
    context: &str,
) -> Result<u32> {
    let value = object
        .get(field)
        .and_then(norito::json::Value::as_u64)
        .ok_or_else(|| eyre!("{context} must be a positive u32"))?;
    if value == 0 || value > u64::from(u32::MAX) {
        return Err(eyre!("{context} must be a positive u32"));
    }
    Ok(u32::try_from(value).expect("value is bounded to u32"))
}

fn validate_optional_json_positive_u32_field(
    object: &norito::json::Map,
    field: &str,
    context: &str,
) -> Result<Option<u32>> {
    let Some(value) = object.get(field) else {
        return Ok(None);
    };
    if value.is_null() {
        return Ok(None);
    }
    let value = value
        .as_u64()
        .ok_or_else(|| eyre!("{context} must be a positive u32"))?;
    if value == 0 || value > u64::from(u32::MAX) {
        return Err(eyre!("{context} must be a positive u32"));
    }
    Ok(Some(u32::try_from(value).expect("value is bounded to u32")))
}

