    /// or the typed JSON payload cannot be decoded.
    pub fn get_transaction_status_response_local(
        &self,
        hash: HashOf<SignedTransaction>,
    ) -> Result<Option<PipelineTransactionStatusResponse>> {
        self.get_transaction_status_response_with_scope(hash, Some("local"))
    }

    /// GET `/v1/pipeline/transactions/status?scope=global` — typed pipeline status lookup
    /// using explicit global/fanout routing.
    ///
    /// # Errors
    /// Returns an error if the HTTP request fails, the response has an unexpected content type,
    /// or the typed JSON payload cannot be decoded.
    pub fn get_transaction_status_response_auto(
        &self,
        hash: HashOf<SignedTransaction>,
    ) -> Result<Option<PipelineTransactionStatusResponse>> {
        self.get_transaction_status_response_with_scope(hash, Some("global"))
    }

    /// GET `/v1/triggers/completed` — list historical trigger completions from committed blocks.
    ///
    /// # Errors
    /// Returns an error if the HTTP request fails, the response has an unexpected content type,
    /// or the typed JSON payload cannot be decoded.
    #[allow(clippy::too_many_arguments)]
    pub fn get_trigger_completions(
        &self,
        trigger_id: Option<&str>,
        entrypoint_hash: Option<&str>,
        outcome: Option<&str>,
        from_height: Option<u64>,
        to_height: Option<u64>,
        limit: Option<u64>,
        scan_limit_blocks: Option<u64>,
    ) -> Result<TriggerCompletionListResponse> {
        let url = join_torii_url(&self.torii_url, "v1/triggers/completed");
        let mut builder = self
            .default_request(HttpMethod::GET, url)
            .header("Accept", APPLICATION_JSON);
        if let Some(trigger_id) = trigger_id {
            builder = builder.param("id", trigger_id);
        }
        if let Some(entrypoint_hash) = entrypoint_hash {
            builder = builder.param("entrypoint_hash", entrypoint_hash);
        }
        if let Some(outcome) = outcome {
            builder = builder.param("outcome", outcome);
        }
        if let Some(from_height) = from_height {
            builder = builder.param("from_height", &from_height.to_string());
        }
        if let Some(to_height) = to_height {
            builder = builder.param("to_height", &to_height.to_string());
        }
        if let Some(limit) = limit {
            builder = builder.param("limit", &limit.to_string());
        }
        if let Some(scan_limit_blocks) = scan_limit_blocks {
            builder = builder.param("scan_limit_blocks", &scan_limit_blocks.to_string());
        }
        let resp = self.send_builder(builder)?;
        match resp.status() {
            StatusCode::OK | StatusCode::ACCEPTED => {
                Self::parse_typed_json_ok_response(&resp, "Failed to get trigger completions")
            }
            status => Err(eyre!(
                "Failed to get trigger completions: {} {}",
                status,
                std::str::from_utf8(resp.body()).unwrap_or("")
            )),
        }
    }

    /// GET `/v1/pipeline/transactions/status` — convenience status lookup mapped to [`TxConfirmationStatus`].
    ///
    /// # Errors
    /// Returns an error if the HTTP request fails, the response has an unexpected content type,
    /// or the typed JSON payload cannot be decoded.
    pub fn get_transaction_status(
        &self,
        hash: HashOf<SignedTransaction>,
    ) -> Result<Option<TxConfirmationStatus>> {
        Ok(self
            .get_transaction_status_response(hash)?
            .as_ref()
            .and_then(tx_confirmation_status_from_pipeline_response))
    }

    /// Poll `/v1/pipeline/transactions/status` until the transaction reaches a configured stop state.
    ///
    /// Applied, rejected, and expired always stop the wait because they are terminal outcomes.
    ///
    /// # Errors
    /// Returns an error if polling fails consistently, the endpoint returns an unknown status kind,
    /// or the timeout elapses before a stop state is observed.
    pub fn wait_for_transaction_terminal_status(
        &self,
        hash: HashOf<SignedTransaction>,
        options: TransactionWaitOptions,
    ) -> Result<TransactionWaitOutcome> {
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()?;
        rt.block_on(self.wait_for_transaction_terminal_status_async(hash, options))
    }

    async fn wait_for_transaction_terminal_status_async(
        &self,
        hash: HashOf<SignedTransaction>,
        options: TransactionWaitOptions,
    ) -> Result<TransactionWaitOutcome> {
        let TransactionWaitOptions {
            timeout,
            poll_interval,
            terminal_statuses,
        } = options;
        let start = Instant::now();
        let poll_interval = if poll_interval == Duration::ZERO {
            Duration::from_millis(1)
        } else {
            poll_interval
        };
        let stop_statuses = if terminal_statuses.is_empty() {
            TransactionWaitOptions::default().terminal_statuses
        } else {
            terminal_statuses
        };
        let poll_scope = transaction_wait_status_scope(&stop_statuses);
        let target_description = format_transaction_wait_target(&stop_statuses);
        let mut attempts = 0_u64;
        let mut last_status: Option<String> = None;

        loop {
            attempts = attempts.saturating_add(1);
            if let Some(response) =
                self.get_transaction_status_response_with_scope(hash, Some(poll_scope))?
            {
                let kind = response.status.kind.as_str();
                last_status = Some(kind.to_owned());
                if tx_confirmation_status_from_pipeline_response(&response).is_none() {
                    return Err(eyre!(
                        "unsupported pipeline status kind `{kind}` for transaction {}; last_status={kind}",
                        response.hash
                    ));
                }
                if should_stop_waiting_on_pipeline_kind(kind, &stop_statuses) {
                    let block_height = response.status.block_height;
                    let rejection_reason = response.status.rejection_reason.clone();
                    let scope = response.scope.clone();
                    let resolved_from = response.resolved_from.clone();
                    let summary = response.summary.clone();
                    let diagnostics = response.diagnostics.clone();
                    let trigger_completions = response.trigger_completions.clone();
                    return Ok(TransactionWaitOutcome {
                        hash: response.hash.clone(),
                        terminal_kind: kind.to_owned(),
                        attempts,
                        elapsed_ms: elapsed_ms_u64(start.elapsed()),
                        block_height,
                        rejection_reason,
                        scope,
                        resolved_from,
                        summary,
                        diagnostics,
                        trigger_completions,
                        r#final: response,
                    });
                }
                if should_error_on_unrequested_transaction_failure(kind, &stop_statuses) {
                    return Err(eyre!(
                        "transaction {} reached terminal failure status `{kind}` before {target_description}; last_status={kind}",
                        response.hash
                    ));
                }
            }

            let elapsed = start.elapsed();
            if elapsed >= timeout {
                let last_status = last_status.unwrap_or_else(|| "not_observed".to_owned());
                return Err(eyre!(
                    "transaction did not reach {target_description} within {} ms; last_status={last_status}",
                    timeout.as_millis()
                ));
            }
            tokio::time::sleep(poll_interval.min(timeout.saturating_sub(elapsed))).await;
        }
    }

    fn transaction_committed(
        &self,
        hash: HashOf<SignedTransaction>,
        entry_hash: HashOf<TransactionEntrypoint>,
    ) -> Result<Option<TxConfirmationStatus>> {
        use crate::data_model::query::{
            CommittedTxFilters,
            dsl::CompoundPredicate,
            parameters::{FetchSize, Pagination},
            transaction::prelude::FindTransactions,
        };

        let one = NonZeroU64::new(1).expect("nonzero");
        let filters = CommittedTxFilters {
            entry_eq: Some(entry_hash),
            ..Default::default()
        };
        let snapshot = self
            .query(FindTransactions::new())
            .filter(CompoundPredicate::from_filters(filters))
            .with_pagination(Pagination::new(Some(one), 0))
            .with_fetch_size(FetchSize::new(Some(one)))
            .execute_all()?;
        let outcome = snapshot
            .iter()
            .find(|tx| Self::committed_transaction_matches_hash(tx, hash, entry_hash))
            .map(|tx| tx_confirmation_status_from_committed_result(tx.result()));
        debug!(
            %hash,
            snapshot_len = snapshot.len(),
            found = outcome.is_some(),
            "transaction_committed snapshot check"
        );
        Ok(outcome)
    }

    fn transaction_headers_without_content_type(&self) -> HashMap<String, String> {
        let mut headers = self.headers.clone();
        headers.retain(|name, _| !name.eq_ignore_ascii_case("content-type"));
        headers
    }

    fn prepare_transaction_payload_request<B: RequestBuilder>(
        &self,
        payload: &PreparedTransactionPayload,
    ) -> B {
        // Public Torii ingress accepts a versioned SignedTransaction; internal
        // TransactionEntrypoint wrapping happens on the server boundary.
        B::new(
            HttpMethod::POST,
            join_torii_url(&self.torii_url, torii_uri::TRANSACTION),
        )
        .headers(self.transaction_headers_without_content_type())
        .header("Content-Type", APPLICATION_NORITO)
        .header("Accept", self.wire_format_preference.accept_header())
        .body(payload.as_bytes().to_vec())
    }

    /// Submits and waits until the transaction is either rejected or committed.
    /// Returns rejection reason if transaction was rejected.
    ///
    /// # Errors
    /// Fails if sending transaction to peer fails or if it response with error
    pub fn submit_blocking<I>(
        &self,
        instruction: I,
        fee_payment: FeePaymentIntent,
    ) -> Result<HashOf<SignedTransaction>>
    where
        I: Into<InstructionBox>,
    {
        self.submit_all_blocking(core::iter::once(instruction), fee_payment)
    }

    /// Submits and waits until the transaction is either rejected or committed.
    /// Returns rejection reason if transaction was rejected.
    ///
    /// # Errors
    /// Fails if sending transaction to peer fails or if it response with error
    pub fn submit_all_blocking<I>(
        &self,
        instructions: impl IntoIterator<Item = I>,
        fee_payment: FeePaymentIntent,
    ) -> Result<HashOf<SignedTransaction>>
    where
        I: Into<InstructionBox>,
    {
        self.submit_all_blocking_with_metadata(instructions, fee_payment, Metadata::default())
    }

    /// Submits and waits until the transaction is either rejected or committed.
    /// Allows to specify [`Metadata`] of [`TransactionBuilder`].
    /// Returns rejection reason if transaction was rejected.
    ///
    /// # Errors
    /// Fails if sending transaction to peer fails or if it response with error
    pub fn submit_blocking_with_metadata<I>(
        &self,
        instruction: I,
        fee_payment: FeePaymentIntent,
        metadata: Metadata,
    ) -> Result<HashOf<SignedTransaction>>
    where
        I: Into<InstructionBox>,
    {
        self.submit_all_blocking_with_metadata(core::iter::once(instruction), fee_payment, metadata)
    }

    /// Submits and waits until the transaction is either rejected or committed.
    /// Allows to specify [`Metadata`] of [`TransactionBuilder`].
    /// Returns rejection reason if transaction was rejected.
    ///
    /// # Errors
    /// Fails if sending transaction to peer fails or if it response with error
    pub fn submit_all_blocking_with_metadata<I>(
        &self,
        instructions: impl IntoIterator<Item = I>,
        fee_payment: FeePaymentIntent,
        metadata: Metadata,
    ) -> Result<HashOf<SignedTransaction>>
    where
        I: Into<InstructionBox>,
    {
        const MULTISIG_SIGNATORY: &str = "MULTISIG_SIGNATORY";
        let instructions: Vec<InstructionBox> = instructions.into_iter().map(Into::into).collect();

        // Guard against reserved multisig role names being registered by regular clients.
        // Server-side executors should enforce this, but we also short-circuit here to
        // avoid committing an invalid transaction when the executor is missing the check.
        for instr in &instructions {
            if let Some(RegisterBox::Role(register_role)) =
                instr.as_any().downcast_ref::<RegisterBox>()
                && register_role
                    .object()
                    .id()
                    .name()
                    .as_ref()
                    .starts_with(MULTISIG_SIGNATORY)
            {
                return Err(eyre!(
                    "reserved multisig role names may not be registered by clients"
                ));
            }
        }

        let payload =
            self.try_build_transaction_payload_from_items(instructions, fee_payment, metadata)?;
        let transaction = self.quote_and_sign_transaction_payload(payload)?;
        self.submit_transaction_blocking(&transaction)
    }

