        recent
            .as_object_mut()
            .and_then(|root| root.get_mut("items"))
            .and_then(JsonValue::as_array_mut)
            .and_then(|items| items.first_mut())
            .and_then(JsonValue::as_object_mut)
            .and_then(|item| item.get_mut("links"))
